package com.adc.application;

import com.adc.domain.appointmentbooking.AppointmentBookingRules;
import com.adc.domain.patients.PatientRules;
import com.adc.domain.shared.*;
import com.adc.identity.IdentityGate;
import com.adc.identity.IdentityGate.Identity;
import com.adc.infrastructure.*;
import java.time.*;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import tools.jackson.databind.json.JsonMapper;

@Service @Transactional(isolation=Isolation.READ_COMMITTED,rollbackFor=Exception.class)
public class AppointmentBookingService implements ReceiptPolicy {
    private final AtomicCommandExecutor commands;private final IdentityGate gate;private final AppointmentBookingStore store;private final ScheduleStore schedules;private final PatientStore patients;private final BusinessRowLocks locks;private final AuditWriter audit;private final Clock clock;private static final JsonMapper JSON=JsonMapper.builder().build();
    public AppointmentBookingService(AtomicCommandExecutor commands,IdentityGate gate,AppointmentBookingStore store,ScheduleStore schedules,PatientStore patients,BusinessRowLocks locks,AuditWriter audit,Clock clock){this.commands=commands;this.gate=gate;this.store=store;this.schedules=schedules;this.patients=patients;this.locks=locks;this.audit=audit;this.clock=clock;}
    public record Declaration(String status,List<Map<String,Object>> records,boolean confirmed) { }
    public record Creation(long clinic,long schedule,Instant at,List<Long> treatments,String allergyReference,Long patient,String verification,Map<String,Object> details,Declaration declaration) { }
    private long patient(Identity actor,Creation input){if(actor.subjectType().equals("PATIENT")){if(input.patient!=null || input.verification!=null)throw new DomainFailure(403,"PATIENT_ID_NOT_ACCEPTED");long patient=store.bound(actor.subjectId());gate.requirePatient(actor,patient);return patient;}gate.requireStaff(actor,"RECEPTION","createAppointment",input.clinic);if(input.patient==null || !patients.verification(actor.subjectId(),input.patient,input.verification,List.of(input.clinic)))throw new DomainFailure(403,"PATIENT_VERIFICATION_REQUIRED");return input.patient;}
    private void details(long patient,Creation input,boolean nativePatient){PatientRules.details(input.details,false);var current=patients.view(patient);for(var field:input.details.entrySet())if(!Objects.equals(field.getValue(),current.get(field.getKey())))throw new DomainFailure(422,"PATIENT_DETAILS_CONFLICT");var declaration=input.declaration;if(declaration==null || !declaration.confirmed || declaration.records==null || !Objects.equals(input.allergyReference,current.get("allergy_confirmation_reference")) || input.allergyReference==null || !Objects.equals(declaration.status,current.get("allergy_review_status")) || (declaration.status.equals("NOT_REVIEWED") && !(nativePatient && "SELF_DECLARED".equals(current.get("registration_method")) && input.allergyReference.startsWith("SD1:"))))throw new DomainFailure(422,"ALLERGY_CONFIRMATION_REQUIRED");var expected=new TreeMap<String,Object>();for(var row:patients.allergyRows(patient))if(!Boolean.TRUE.equals(row.get("is_retracted")))expected.put((String)row.get("allergy_id"),row.get("severity_note"));var provided=new TreeMap<String,Object>();for(var row:declaration.records){if(!Set.of("allergy_id","severity_note").containsAll(row.keySet()) || !(row.get("allergy_id") instanceof String id) || provided.containsKey(id))throw new DomainFailure(422,"ALLERGY_DECLARATION_CONFLICT");provided.put(id,row.get("severity_note"));}if(!provided.equals(expected))throw new DomainFailure(422,"ALLERGY_DECLARATION_CONFLICT");}
    public record Validated(long patient,ScheduleStore.Schedule schedule) { }
    public Validated validate(Identity actor,Creation input){
        var hint=schedules.get(input.schedule);locks.acquire(new BusinessRowLocks.Plan(Set.of(hint.dentist()),Set.of(input.schedule),Set.of()));var schedule=schedules.get(input.schedule);
        if(schedule.dentist()!=hint.dentist()||schedule.clinic()!=input.clinic)throw new DomainFailure(422,"SCHEDULE_CLINIC_MISMATCH");long patient=patient(actor,input);patients.lock(patient);details(patient,input,actor.subjectType().equals("PATIENT"));AppointmentBookingRules.slot(schedule,input.at,clock.instant());schedules.eligible(schedule.dentist(),schedule.clinic(),schedule.date());store.treatments(schedule.dentist(),schedule.date(),input.treatments,true);return new Validated(patient,schedule);
    }
    public Map<String,Object> create(AtomicCommandExecutor.Command command,Creation input)throws Exception{
        var result=commands.execute(command,actor->patient(actor,input),actor->{var hint=schedules.get(input.schedule);locks.acquire(new BusinessRowLocks.Plan(Set.of(hint.dentist()),Set.of(input.schedule),Set.of()));var schedule=schedules.get(input.schedule);if(schedule.dentist()!=hint.dentist() || schedule.clinic()!=input.clinic)throw new DomainFailure(422,"SCHEDULE_CLINIC_MISMATCH");long patient=patient(actor,input);patients.lock(patient);details(patient,input,actor.subjectType().equals("PATIENT"));AppointmentBookingRules.slot(schedule,input.at,clock.instant());schedules.eligible(schedule.dentist(),schedule.clinic(),schedule.date());store.treatments(schedule.dentist(),schedule.date(),input.treatments,true);if(store.registrationFee(input.clinic,schedule.dentist())>0)throw new DomainFailure(409,"REGISTRATION_PAYMENT_REQUIRED");if(store.occupied(schedule.dentist(),input.at,schedule.slot()))throw new DomainFailure(409,"SLOT_OCCUPIED");long id=store.create(patient,schedule,input.at,input.treatments,actor.subjectType().equals("PATIENT")?"PATIENT":"RECEPTION",actor.subjectId(),command.key());return new AtomicCommandExecutor.Result(JSON.writeValueAsString(List.of("Appointment:"+id)),JSON.writeValueAsString(Map.of("appointment_id",Long.toString(id))),200,"Appointment",Long.toString(id),List.of(input.clinic),null,input.verification);});long id=Long.parseLong(JSON.readTree(result.summary()).get("appointment_id").asText());var actor=gate.authenticate(command.token(),command.client());access(actor,id,"createAppointment");return store.view(id);
    }
    private List<Long> readScopes(Identity actor,String operation){var allowed=new TreeSet<Long>();for(String role:List.of("RECEPTION","DENTIST","CASHIER")){if(role.equals("DENTIST") && actor.dentistId()==null)continue;try{for(long clinic:gate.staffClinics(actor,role,operation)){if(role.equals("DENTIST"))try{schedules.eligible(actor.dentistId(),clinic,clock.instant().atZone(BusinessTime.ZONE).toLocalDate());}catch(DomainFailure invalid){if(invalid.status()!=422)throw invalid;continue;}allowed.add(clinic);}}catch(DomainFailure denied){if(denied.status()!=403)throw denied;}}if(allowed.isEmpty())throw new DomainFailure(403,"ACCESS_DENIED");return List.copyOf(allowed);}
    private void access(Identity actor,long id,String operation){var view=store.view(id);if(actor.subjectType().equals("PATIENT"))gate.requirePatient(actor,Long.parseLong((String)view.get("patient_id")));else if(!readScopes(actor,operation).contains(Long.parseLong((String)view.get("clinic_id"))))throw new DomainFailure(403,"ACCESS_DENIED");}
    public Map<String,Object> get(String token,String client,long id,String request){var actor=gate.authenticate(token,client);access(actor,id,"getAppointment");var view=store.view(id);audit.success(actor,"getAppointment","Appointment",Long.toString(id),List.of(Long.parseLong((String)view.get("clinic_id"))),request);return view;}
    public Map<String,Object> candidates(String token,String client,long clinic,List<Long> treatments,Instant start,Instant end,String cursor,int limit,String request){
        var actor=gate.authenticate(token,client);if(!actor.subjectType().equals("PATIENT"))gate.requireStaff(actor,"RECEPTION","searchAppointmentCandidates",clinic);
        if(start==null || end==null || !end.isAfter(start) || limit<1 || limit>100 || treatments==null || new HashSet<>(treatments).size()!=treatments.size())throw new DomainFailure(400,"INVALID_REQUEST");
        Instant after=Instant.MIN;long afterSchedule=0;if(cursor!=null)try{String[] values=new String(Base64.getUrlDecoder().decode(cursor),java.nio.charset.StandardCharsets.UTF_8).split("/",-1);if(values.length!=2)throw new IllegalArgumentException();after=Instant.ofEpochSecond(Long.parseLong(values[0]));afterSchedule=BusinessValues.id(values[1]);}catch(IllegalArgumentException error){throw new DomainFailure(400,"INVALID_REQUEST");}
        var found=new ArrayList<Map<String,Object>>();for(var schedule:schedules.list(List.of(clinic),null,start,end,0,Integer.MAX_VALUE)){
            if(!schedule.status().equals("NORMAL"))continue;try{schedules.eligible(schedule.dentist(),clinic,schedule.date());store.treatments(schedule.dentist(),schedule.date(),treatments,false);}catch(DomainFailure failure){if(failure.status()!=422)throw failure;continue;}
            var windows=store.candidateWindows(schedule.dentist(),start,end);var profile=store.doctorProfile(schedule.dentist());long fee=store.registrationFee(clinic,schedule.dentist());
            for(Instant at=schedule.starts();at.isBefore(schedule.ends());at=at.plusSeconds(schedule.slot()*60L)){Instant slotAt=at;if(at.isBefore(start) || !at.isBefore(end) || !at.isAfter(clock.instant()) || at.isBefore(after) || (at.equals(after) && schedule.id()<=afterSchedule) || windows.stream().anyMatch(w->w.overlaps(slotAt,schedule.slot())))continue;var candidate=new LinkedHashMap<String,Object>();candidate.putAll(profile);candidate.put("clinic_id",Long.toString(clinic));candidate.put("dentist_id",Long.toString(schedule.dentist()));candidate.put("schedule_id",Long.toString(schedule.id()));candidate.put("starts_at",at.toString());candidate.put("ends_at",at.plusSeconds(schedule.slot()*60L).toString());candidate.put("registration_fee_fen",fee);found.add(candidate);}
        }
        found.sort(Comparator.<Map<String,Object>,Instant>comparing(row->Instant.parse((String)row.get("starts_at"))).thenComparingLong(row->Long.parseLong((String)row.get("schedule_id"))));String next=null;if(found.size()>limit){var last=found.get(limit-1);next=Base64.getUrlEncoder().withoutPadding().encodeToString((Instant.parse((String)last.get("starts_at")).getEpochSecond()+"/"+last.get("schedule_id")).getBytes(java.nio.charset.StandardCharsets.UTF_8));found=new ArrayList<>(found.subList(0,limit));}audit.success(actor,"searchAppointmentCandidates","DentistSchedule",null,List.of(clinic),request);var page=new LinkedHashMap<String,Object>();page.put("items",found);page.put("next_cursor",next);return page;
    }
    public Map<String,Object> list(String token,String client,Long clinic,Instant start,Instant end,String status,String cursor,int limit,String request){var actor=gate.authenticate(token,client);Long patient=null;List<Long> scope=null;if(actor.subjectType().equals("PATIENT")){patient=store.bound(actor.subjectId());gate.requirePatient(actor,patient);if(clinic!=null)scope=List.of(clinic);}else{scope=readScopes(actor,"listAppointments");if(clinic!=null){if(!scope.contains(clinic))throw new DomainFailure(403,"ACCESS_DENIED");scope=List.of(clinic);}}if(limit<1 || limit>100 || (start!=null && end!=null && !end.isAfter(start)) || (status!=null && !Set.of("SCHEDULED","IN_PROGRESS","COMPLETED","INVOICED","CANCELLED").contains(status)))throw new DomainFailure(400,"INVALID_REQUEST");var rows=store.list(patient,scope,start,end,status,cursor==null?0:BusinessValues.id(cursor),limit+1);String next=null;if(rows.size()>limit){rows=rows.subList(0,limit);next=(String)rows.getLast().get("appointment_id");}audit.success(actor,"listAppointments","Appointment",null,scope==null?List.of():scope,request);var page=new LinkedHashMap<String,Object>();page.put("items",rows);page.put("next_cursor",next);return page;}
    @Override @Transactional(propagation=Propagation.NOT_SUPPORTED)public Set<String> operations(){return Set.of("createAppointment");}
    @Override public void authorize(Identity actor,String operation,String refs){if(!operations().contains(operation))throw new DomainFailure(403,"ACCESS_DENIED");if(actor.subjectType().equals("PATIENT"))gate.requirePatient(actor,store.bound(actor.subjectId()));else gate.staffClinics(actor,"RECEPTION",operation);if(refs!=null)for(var ref:JSON.readTree(refs)){String value=ref.asText();if(!value.startsWith("Appointment:"))throw new DomainFailure(403,"ACCESS_DENIED");access(actor,Long.parseLong(value.substring(12)),operation);}}
}


